const { setTimeout: delay } = await import('node:timers/promises');
const seen = [];
const service = submission.createTaskService(async value => { seen.push(value); await delay(15); return value * 2; }, { maxQueued: 1 });
try {
  const first = service.submit(3);
  const second = service.submit(4);
  const third = service.submit(5).catch(error => error.code);
  const during = service.stats();
  const results = await Promise.all([first, second, third]);
  await service.close();
  observe({ during, results, seen, final: service.stats() });
} finally { await service.close(); }

const original = new Error('bad-row');
const observed = [];
const service = submission.createTaskService(value => { if (value === 0) throw original; return value + 10; }, { onError: error => observed.push(error) });
try {
  const first = service.submit(0).catch(error => ({ message: error.message, same: error === original }));
  const second = service.submit(2);
  const results = await Promise.all([first, second]);
  await service.close();
  observe({ results, errorCount: observed.length, sameError: observed[0] === original, stats: service.stats(), errorListeners: service.events.listenerCount('error') });
} finally { await service.close(); }

const { EventEmitter, once } = await import('node:events');
const service = submission.createTaskService(value => value * 3);
try {
  const event = once(service.events, 'settled');
  const result = await service.submit(7);
  const [value] = await event;
  await service.close();
  observe({ isEmitter: service.events instanceof EventEmitter, result, value, listeners: service.events.listenerCount('settled') });
} finally { await service.close(); }

const service = submission.createTaskService(value => value + 1);
const stream = service.watch();
try {
  const pending = stream.next();
  const during = { settled: service.events.listenerCount('settled'), error: service.events.listenerCount('error') };
  await service.submit(8);
  const item = await pending;
  await stream.return();
  const afterReturn = { settled: service.events.listenerCount('settled'), error: service.events.listenerCount('error') };
  await service.close();
  observe({ during, item, afterReturn, finalErrorListeners: service.events.listenerCount('error') });
} finally { await service.close(); await stream.return(); }

const original = new Error('stream-failure');
const service = submission.createTaskService(() => { throw original; });
const stream = service.watch();
try {
  const pending = stream.next().catch(error => ({ message: error.message, same: error === original }));
  await service.submit(1).catch(() => {});
  const failure = await pending;
  await service.close();
  observe({ failure, settledListeners: service.events.listenerCount('settled'), errorListeners: service.events.listenerCount('error') });
} finally { await service.close(); await stream.return(); }

const { setTimeout: delay } = await import('node:timers/promises');
const service = submission.createTaskService(async value => { await delay(12); return value; }, { maxQueued: 2 });
try {
  const first = service.submit('a');
  const second = service.submit('b');
  const closing = service.close();
  const repeated = service.close();
  const during = service.stats();
  const rejected = await service.submit('c').catch(error => error.code);
  const results = await Promise.all([first, second]);
  await closing;
  observe({ sameClose: closing === repeated, during, rejected, results, final: service.stats(), listeners: service.events.eventNames().length });
} finally { await service.close(); }

const service = submission.createTaskService(value => value);
const stream = service.watch();
try {
  const pending = stream.next();
  const first = service.close();
  const second = service.close();
  await first;
  const item = await pending;
  const rejected = await service.submit(0).catch(error => error.code);
  observe({ sameClose: first === second, done: item.done, rejected, stats: service.stats(), listenerCount: service.events.eventNames().length });
} finally { await service.close(); await stream.return(); }

const service = submission.createTaskService(value => value);
let notices = 0;
const external = () => { notices += 1; };
service.events.on('notice', external);
await service.close();
service.events.emit('notice');
observe({ notices, externalListeners: service.events.listenerCount('notice'), ownErrorListeners: service.events.listenerCount('error') });
service.events.off('notice', external);

const failures = [];
for (const [handler, options] of [[null, {}], [x => x, { maxQueued: -1 }], [x => x, { maxQueued: 33 }], [x => x, { onError: 7 }]]) {
  let service;
  try { service = submission.createTaskService(handler, options); failures.push('accepted'); }
  catch (error) { failures.push(error.name); }
  finally { if (service) await service.close(); }
}
observe(failures);

const service = submission.createTaskService(value => value);
const stream = service.watch();
let guard;
try {
  const pending = stream.next();
  const returning = stream.return();
  const settled = await Promise.race([
    Promise.all([pending, returning]),
    new Promise((_, reject) => { guard = setTimeout(() => reject(new Error('Case safety deadline: watch return did not finish')), 1000); })
  ]);
  clearTimeout(guard);
  observe({ nextDone: settled[0].done, returnDone: settled[1].done, state: service.stats().state, settledListeners: service.events.listenerCount('settled'), errorListeners: service.events.listenerCount('error') });
} finally {
  clearTimeout(guard);
  await service.close();
  await stream.return();
}
